import sys

def solve():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    first_line = input_data[0].split(' ', 1)
    if len(first_line) < 2:
        return

    t_str, m = first_line
    try:
        t = int(t_str)
    except ValueError:
        return

    # Create mapping from Bytelandian char to English char
    # M is the English translation of "abcdefghijklmnopqrstuvwxyz"
    # So M[i] is the English letter corresponding to Bytelandian chr(ord('a') + i)
    bytelandian_to_english = {}
    base_alphabet = "abcdefghijklmnopqrstuvwxyz"

    for i in range(26):
        bytelandian_char = base_alphabet[i]
        english_char = m[i]
        bytelandian_to_english[bytelandian_char] = english_char
        bytelandian_to_english[bytelandian_char.upper()] = english_char.upper()

    results = []

    for i in range(1, t + 1):
        if i >= len(input_data):
            break
        sentence = input_data[i]
        translated_chars = []

        for char in sentence:
            if char == '_':
                translated_chars.append(' ')
            elif char in bytelandian_to_english:
                translated_chars.append(bytelandian_to_english[char])
            else:
                translated_chars.append(char)

        results.append("".join(translated_chars))

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
